class Solution:
    def isValidSudoku(self, board: List[List[str]]) -> bool:
        for r in range(9):
            for c in range(9):
                val = board[r][c]
                if val == ".":
                    continue

                for c2 in range(9):
                    if c2 != c and board[r][c2] == val:
                        return False

                for r2 in range(9):
                    if r2 != r and board[r2][c] == val:
                        return False

                br, bc = 3 * (r // 3), 3 * (c // 3)
                for r2 in range(br, br + 3):
                    for c2 in range(bc, bc + 3):
                        if (r2, c2) != (r, c) and board[r2][c2] == val:
                            return False

        return True
